// Real (non-extrapolated) crossover-point measurement at large N. Uses
// synthetic order books generated by scripts/gen_synthetic_book.py, since
// the sample CSVs under ~/Downloads only go up to 1000 ticks.
use std::time::Instant;
use zk_fba_csv_full::{full_pipeline, OrderBook};

fn bench_one(label: &str, path: &str) {
    let book = OrderBook::from_csv(path);
    let mut rng = ark_std::test_rng();
    let t = Instant::now();
    let result = full_pipeline(&book, &mut rng);
    let elapsed = t.elapsed();
    println!(
        "{:<28}  n={:<6}  domain={:<6}  V_max={:<6}  total={:>9.1?}  all_pass={}",
        label,
        book.n,
        book.domain_size,
        book.v_max,
        elapsed,
        result.all_pass()
    );
}

fn main() {
    bench_one("100-tick",   "/Users/kimiaesmaili/Downloads/order_book_100_log-normal.csv");
    bench_one("1000-tick",  "/Users/kimiaesmaili/Downloads/order_book_1000_log-normal.csv");
    bench_one("5000-tick",  "/Users/kimiaesmaili/Downloads/order_book_5000_log-normal.csv");
    bench_one("10000-tick", "/Users/kimiaesmaili/Downloads/order_book_10000_log-normal.csv");
    bench_one("20000-tick", "/Users/kimiaesmaili/Downloads/order_book_20000_log-normal.csv");
}
